#!/bin/sh

# Files path for PuffinMRMD
MRMD_FILES_PATH="/var/lib/data/puffinmrmd"
# Temporary files path.
TEMP_FILES_PATH="${MRMD_FILES_PATH}/tmp"
# Persistent data folder to keep user data and run time data
# generated by puffinmrmd that will be kept after system OTA.
PERSISTENT_FILES_PATH="${MRMD_FILES_PATH}/data"

install -o root -g system -d $MRMD_FILES_PATH
install -o root -g system -d $PERSISTENT_FILES_PATH
install -o root -g system -d $TEMP_FILES_PATH

chmod 775 $MRMD_FILES_PATH
chmod 775 $PERSISTENT_FILES_PATH
chmod 775 $TEMP_FILES_PATH